// WithoutModelHooks acknowledges that set-based writes on this query skip per-model hooks and observers; per-model writes on it are rejected.
func (q TargetQuery) WithoutModelHooks() TargetQuery { q.Query = q.Query.WithoutModelHooks(); return q }

// UpdateAll assigns the draft to every model matching this query (filters, global scopes and soft-delete visibility) in one UPDATE and returns the affected count. Managed update timestamps and field mutators apply once; per-model hooks, observers and change capture do not run.
func (q TargetQuery) UpdateAll(ctx context.Context, writer database.Transactor, draft TargetDraft) (int64, error) {
	mutation, err := draft.foundryMutation(false)
	if err != nil {
		return 0, err
	}
	return q.Query.PatchAll(ctx, writer, mutation)
}

// DeleteAll soft-deletes every active model matching this query in one statement and returns the affected count. Per-model hooks do not run.
func (q TargetQuery) DeleteAll(ctx context.Context, writer database.Transactor) (int64, error) {
	return q.Query.RemoveAll(ctx, writer)
}

// ForceDeleteAll physically deletes every model matching this query's current visibility in one statement. WithTrashed includes deleted models.
func (q TargetQuery) ForceDeleteAll(ctx context.Context, writer database.Transactor) (int64, error) {
	return q.Query.ForceRemoveAll(ctx, writer)
}

// Increment adjusts one numeric field of every matching model by a typed delta, such as TargetFields().Field.By(1), with an optional extra draft, in one UPDATE. SQL NULL stays NULL. Per-model hooks do not run.
func (q TargetQuery) Increment(ctx context.Context, writer database.Transactor, adjustment foundryquery.Adjustment[Target], extra ...TargetDraft) (int64, error) {
	if len(extra) > 1 {
		return 0, foundryfault.New(foundryfault.Invalid, "numeric adjustment accepts at most one extra draft")
	}
	var mutation foundryquery.Mutation[Target]
	if len(extra) == 1 {
		var err error
		if mutation, err = extra[0].foundryMutation(false); err != nil {
			return 0, err
		}
	}
	return q.Query.AdjustAll(ctx, writer, adjustment, false, mutation)
}

// Decrement adjusts one numeric field of every matching model by a typed delta, such as TargetFields().Field.By(1), with an optional extra draft, in one UPDATE. SQL NULL stays NULL. Per-model hooks do not run.
func (q TargetQuery) Decrement(ctx context.Context, writer database.Transactor, adjustment foundryquery.Adjustment[Target], extra ...TargetDraft) (int64, error) {
	if len(extra) > 1 {
		return 0, foundryfault.New(foundryfault.Invalid, "numeric adjustment accepts at most one extra draft")
	}
	var mutation foundryquery.Mutation[Target]
	if len(extra) == 1 {
		var err error
		if mutation, err = extra[0].foundryMutation(false); err != nil {
			return 0, err
		}
	}
	return q.Query.AdjustAll(ctx, writer, adjustment, true, mutation)
}

// FoundryUpdateMutation supplies the typed update-draft adapter for framework integrations such as pivot updates. Omitted fields stay unchanged; no mutators or database calls run here.
func (d TargetDraft) FoundryUpdateMutation() (foundryquery.Mutation[Target], error) {
	return d.foundryMutation(false)
}

// FoundryCreateMutation supplies the typed draft adapter for framework integrations. Defaults fill omitted fields before UUID preparation; no mutators or database calls run here.
func (d TargetDraft) FoundryCreateMutation(defaults foundryquery.Mutation[Target]) (foundryquery.Mutation[Target], error) {
	values, err := foundryquery.ReadCreateDefaults(QueryJoinedTargets().Query, defaults)
	if err != nil {
		return foundryquery.Mutation[Target]{}, err
	}
	if !d.fieldID.IsSet() {
		v, err := foundryquery.MutationValue[Target, int64](values, "joined_targets", "id")
		if err != nil {
			return foundryquery.Mutation[Target]{}, err
		}
		d.fieldID = v
	}
	if !d.fieldParentID.IsSet() {
		v, err := foundryquery.MutationValue[Target, int64](values, "joined_targets", "parent_id")
		if err != nil {
			return foundryquery.Mutation[Target]{}, err
		}
		d.fieldParentID = v
	}
	if !d.fieldName.IsSet() {
		v, err := foundryquery.MutationValue[Target, string](values, "joined_targets", "name")
		if err != nil {
			return foundryquery.Mutation[Target]{}, err
		}
		d.fieldName = v
	}
	if !d.fieldRank.IsSet() {
		v, err := foundryquery.MutationValue[Target, int64](values, "joined_targets", "rank")
		if err != nil {
			return foundryquery.Mutation[Target]{}, err
		}
		d.fieldRank = v
	}
	if !d.fieldDeletedAt.IsSet() {
		v, err := foundryquery.MutationValue[Target, foundryvalue.Nullable[temporal.DateTime]](values, "joined_targets", "deleted_at")
		if err != nil {
			return foundryquery.Mutation[Target]{}, err
		}
		d.fieldDeletedAt = v
	}
	return d.foundryMutation(true)
}
func (d TargetDraft) foundryMutation(create bool) (foundryquery.Mutation[Target], error) {
	var assignments []foundryquery.Assignment[Target]
	if v, set := d.fieldID.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Target]("joined_targets", "id", codec.Signed[int64](), v))
	}
	if v, set := d.fieldParentID.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Target]("joined_targets", "parent_id", codec.Signed[int64](), v))
	}
	if v, set := d.fieldName.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Target]("joined_targets", "name", codec.String[string](), v))
	}
	if v, set := d.fieldRank.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Target]("joined_targets", "rank", codec.Signed[int64](), v))
	}
	if v, set := d.fieldDeletedAt.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Target]("joined_targets", "deleted_at", codec.Nullable(codec.DateTime()), v))
	}
	return foundryquery.Change(assignments...), nil
}

// TargetRelationSet requires typed descriptors matching every declared relation slot.
type TargetRelationSet struct {
	Parent  foundryquery.OneRelation[Target, Parent]
	Inverse foundryquery.ThroughRelation[Target, Parent, Pivot]
}

var foundryTargetRelations foundryquery.Memo[TargetRelationSet]

func foundryTargetBuildRelations() TargetRelationSet {
	relations := defineTargetRelations()
	relations.Parent = relations.Parent.Bind("Parent", QueryJoinedTargets().Query, foundryquery.ModelQueryOf[Parent](), func(m Target) relation.One[Parent] { return m.Parent }, func(m Target, loaded relation.One[Parent]) Target { m.Parent = loaded; return m })
	relations.Inverse = relations.Inverse.Bind("Inverse", QueryJoinedTargets().Query, foundryquery.ModelQueryOf[Parent](), foundryquery.ModelQueryOf[Pivot](), func(m Target) relation.Through[Parent, Pivot] { return m.Inverse }, func(m Target, loaded relation.Through[Parent, Pivot]) Target { m.Inverse = loaded; return m })
	return relations
}

// TargetRelations binds handwritten key declarations to generated model metadata and typed slots.
// defineTargetRelations runs once per process; its immutable descriptors are shared.
func TargetRelations() TargetRelationSet {
	return foundryTargetRelations.Get(foundryTargetBuildRelations)
}

